// Bundles the runtime npm dependencies into lib/deps.js (committed), so the app runs straight
// from the GitHub repo zip without npm install. Re-run after changing dependencies.
require('esbuild').buildSync({
  stdin: { contents: "module.exports = { AdmZip: require('adm-zip'), Auth: require('msmc').Auth };", resolveDir: __dirname + '/..' },
  bundle: true, platform: 'node', format: 'cjs', target: 'node22',
  external: ['electron', 'encoding'], // electron is provided at runtime; encoding is an unused optional dep of node-fetch
  outfile: __dirname + '/../lib/deps.js',
  banner: { js: '// Generated by scripts/bundle-deps.js — do not edit.' },
});
console.log('Wrote lib/deps.js');
